/// <summary>
/// Extension of Postload and creation of new method to get the tax fields
/// </summary>
[ExtensionOf(tableStr(FreeTextInvoiceLineEntity))]
public final class METFreeTextInvoiceLineEntity_Extension
{
}

Method.Source:
/// <summary>
/// populating tax fields
/// </summary>
public void postLoad()
{
    next postload();
    this.METGSTAmount       = this.getMETGSTAmount();
    this.METWETAmount       = this.getMETWETAmount();
    this.METTotalTaxAmount  = this.getMETTotalTaxAmount();
}

    /// <summary>
    /// Method to return tax amount
    /// </summary>
    /// <param name = "_taxCode">Tax code (GST, WET)</param>
    /// <returns>Tax amount</returns>
    public TaxAmountCur calculateTaxAmount(TaxCode  _taxCode = '')
    {
        TaxAmountCur    metTaxAmount;

        changecompany(this.DataAreaId)
        {
            TaxTrans            metTaxTrans;
            TaxUncommitted      metTaxUncommitted;
            CustInvoiceTrans    metCustInvoiceTrans;
            CustInvoiceTable    metCustInvoiceTable = CustInvoiceTable::findRecId(this.ParentRecId);

            if (metCustInvoiceTable.InvoiceId)
            {
                // Use the source regulate tax amount from TaxTrans for posted invoice as it includes tax adjustments
                select sum(SourceRegulateAmountCur) from metTaxTrans
                        join LineNum, InvoiceId, InvoiceDate, RecId from metCustInvoiceTrans
                            where metTaxTrans.SourceRecId == metCustInvoiceTrans.RecId
                                && metTaxTrans.SourceTableId == metCustInvoiceTrans.TableId
                                && metCustInvoiceTrans.LineNum == this.LineNumber
                                && metCustInvoiceTrans.InvoiceId == metCustInvoiceTable.InvoiceId
                                && metCustInvoiceTrans.InvoiceDate == metCustInvoiceTable.InvoiceDate
                                && (metTaxTrans.TaxCode == _taxCode || _taxCode == '');

                metTaxAmount = -metTaxTrans.SourceRegulateAmountCur;
            }
            else
            {
                CustInvoiceLine     metCustInvoiceLine;
                select firstonly RecId
                    from metCustInvoiceLine
                    where metCustInvoiceLine.ParentRecId == this.ParentRecId
                && metCustInvoiceLine.LineNum   == this.LineNumber;
                // Get source regulate tax amount from TaxUncommitted for unposted invoice as it includes tax adjustments
                select sum(SourceRegulateAmountCur) from metTaxUncommitted
                where metTaxUncommitted.SourceTableId == tableNum(CustInvoiceLine)
                    && metTaxUncommitted.SourceRecId == this.RecId
                    && (metTaxUncommitted.TaxCode == _taxCode || _taxCode == '');

                metTaxAmount = -metTaxUncommitted.SourceRegulateAmountCur;
            }
        }
        return metTaxAmount;
    }

/// <summary>
/// Get GST amount
/// </summary>
/// <returns>GST amount</returns>
public TaxRegulationAmountCur getMETGSTAmount()
{
    return this.calculateTaxAmount(METConstants::taxGroupGST);
}

/// <summary>
/// Get WET amount
/// </summary>
/// <returns>WET amount</returns>
public TaxRegulationAmountCur getMETWETAmount()
{
    return this.calculateTaxAmount(METConstants::WET);
}

/// <summary>
/// Get total tax amount
/// </summary>
/// <returns>Total tax amount</returns>
public TaxRegulationAmountCur getMETTotalTaxAmount()
{
    return this.calculateTaxAmount();
}
